{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    groups = {}
    for node, g in refinement.items():
        groups.setdefault(g, []).append(node)
    for g in groups:
        groups[g].sort()
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        if gu <= gv:
            key = (gu, gv)
        else:
            key = (gv, gu)
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = sorted([[g1, g2, w] for (g1, g2), w in agg.items()], key=lambda x: (x[0], x[1]))
    members = {g: groups[g] for g in set(refinement.values())}
    return {'aggregate_edges': aggregate_edges, 'members': members}"}
